package com.example.starter.pension.service;

import org.springframework.stereotype.Component;

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

/**
 * 司龄与企业缴费归属比例计算。
 *
 * <p>规则：司龄按入职日至支付申请日（UTC 日界）的整年数计算，恰满档位年限按该档归属；
 * 满 3 年 50%、满 5 年 80%、满 8 年 100%，不足 3 年 0%。个人缴费始终 100% 归属。</p>
 */
@Component
public class VestingCalculator {

    /** 50% 基点。 */
    public static final int RATIO_50_BP = 5000;
    /** 80% 基点。 */
    public static final int RATIO_80_BP = 8000;
    /** 100% 基点。 */
    public static final int RATIO_100_BP = 10000;

    /**
     * 计算完整司龄年数：入职日到申请日之间经过的整年数，不满一年不计。
     *
     * @param hireDate    入职日（UTC）
     * @param requestDate 支付申请日（UTC）
     * @return 完整年数，非负；申请日早于入职日时为 0
     */
    public int hireYears(LocalDate hireDate, LocalDate requestDate) {
        long years = ChronoUnit.YEARS.between(hireDate, requestDate);
        return (int) Math.max(0, years);
    }

    /**
     * 按司龄整年数返回企业缴费归属比例（基点）。
     *
     * @param hireYears 完整司龄年数
     * @return 0 / 5000 / 8000 / 10000
     */
    public int vestedRatioBp(int hireYears) {
        if (hireYears >= 8) {
            return RATIO_100_BP;
        }
        if (hireYears >= 5) {
            return RATIO_80_BP;
        }
        if (hireYears >= 3) {
            return RATIO_50_BP;
        }
        return 0;
    }

    /**
     * 计算企业缴费归属金额，精确到分；比例乘出的不足 1 分部分舍去（不计归属、不划回）。
     *
     * @param enterpriseAmountCents 企业缴费总额，单位：分
     * @param ratioBp               归属比例（基点）
     * @return 归属企业缴费金额，单位：分
     */
    public long vestedEnterprise(long enterpriseAmountCents, int ratioBp) {
        return Math.multiplyExact(enterpriseAmountCents, ratioBp) / 10000L;
    }
}

package com.example.starter.pension.service;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;

/**
 * 幂等指纹工具：对 requestId 与全部业务字段计算 SHA-256，用于同键异参冲突判定。
 */
public final class Fingerprints {

    private Fingerprints() {
    }

    /**
     * 计算 SHA-256 指纹。
     *
     * @param parts 参与指纹的全部业务字段，按固定顺序拼接
     * @return 64 位十六进制指纹
     */
    public static String sha256(String... parts) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            for (String part : parts) {
                digest.update(part == null ? "" : part.getBytes(StandardCharsets.UTF_8));
                digest.update((byte) '|');
            }
            return HexFormat.of().formatHex(digest.digest());
        } catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("当前 JVM 不支持 SHA-256", ex);
        }
    }
}

package com.example.starter.pension.service;

import com.example.starter.pension.repo.InstallmentRepository.NewInstallment;
import org.springframework.stereotype.Component;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

/**
 * 分期排期与金额拆分。
 *
 * <p>各期按月初（UTC）到期：一次性为申请日当月 1 日的 1 期；12/24 期为申请月起连续
 * 各月 1 日。金额精确到分，前 n-1 期按整除均分，尾差（含余数）全部归入最后一期。</p>
 */
@Component
public class InstallmentScheduler {

    /**
     * 生成分期计划。
     *
     * @param totalCents 归属权益快照总额，单位：分
     * @param count      期数（1/12/24）
     * @param firstMonth 首期到期月（通常为申请日所在月，UTC）
     * @return 不可变的期次建账参数列表
     */
    public List<NewInstallment> schedule(long totalCents, int count, LocalDate firstMonth) {
        if (count <= 0) {
            throw new IllegalArgumentException("期数必须为正: " + count);
        }
        if (totalCents < 0) {
            throw new IllegalArgumentException("分期总额不能为负: " + totalCents);
        }
        LocalDate start = firstMonth.withDayOfMonth(1);
        long base = totalCents / count;
        List<NewInstallment> result = new ArrayList<>(count);
        long allocated = 0L;
        for (int i = 1; i <= count; i++) {
            LocalDate due = start.plusMonths(i - 1L);
            long amount = i == count ? totalCents - allocated : base;
            allocated += amount;
            result.add(new NewInstallment(i, due, amount));
        }
        return List.copyOf(result);
    }
}

