                .param("reason", p.reason().name())
                .param("installmentType", p.installmentType().name())
                .param("fingerprint", p.fingerprint())
                .param("requestDate", java.sql.Date.valueOf(p.requestDate()))
                .param("hireYears", p.hireYears())
                .param("vestedRatioBp", p.vestedRatioBp())
                .param("personalAmountCents", p.personalAmountCents())
                .param("enterpriseAmountCents", p.enterpriseAmountCents())
                .param("vestedEnterpriseCents", p.vestedEnterpriseCents())
                .param("vestedTotalCents", p.vestedTotalCents())
                .param("unvestedReturnCents", p.unvestedReturnCents())
                .param("installmentsCount", p.installmentsCount())
                .param("status", p.status().name())
                .param("activeMemberId", p.activeMemberId())
                .param("enterpriseReturned", p.enterpriseReturned())
                .param("originalPlanNo", p.originalPlanNo())
                .param("supplementary", p.supplementary())
                .update()
                .getKey();
        return key.longValue();
    }

