    /**
     * 计划结清（终态）：置 SETTLED、释放成员占用、记录结清时间。
     *
     * @return 受影响行数；0 表示计划已被结清（幂等场景）
     */
    int markSettled(long planId, OffsetDateTime settledAt);

    /**
     * 标记未归属企业缴费已划回企业账户。
