package com.example.starter.pension.service;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

import java.time.LocalDate;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * 司龄整年与企业缴费归属档位的单元测试，重点覆盖“恰满档位年限按该档归属”。
 */
class VestingCalculatorTest {

    private final VestingCalculator calculator = new VestingCalculator();

    @DisplayName("入职日到申请日的整年计算与档位比例边界")
    @ParameterizedTest(name = "{0} 入职、{1} 申请 -> {2} 年, {3} bp")
    @CsvSource({
            // 恰满 3/5/8 年，按该档归属
            "2023-09-25,2026-09-25,3,5000",
            "2021-09-25,2026-09-25,5,8000",
            "2018-09-25,2026-09-25,8,10000",
            // 差一天不满 3 年 -> 0%
            "2023-09-26,2026-09-25,2,0",
            // 满 3 后差一天不满 5 -> 仍 50%
            "2021-09-26,2026-09-25,4,5000",
            // 满 5 后差一天不满 8 -> 仍 80%
            "2018-09-26,2026-09-25,7,8000",
            // 超过 8 年 -> 100%
            "2010-01-01,2026-09-25,16,10000",
            // 闰年 2 月 29 入职
            "2024-02-29,2026-02-28,1,0"
    })
    void hireYearsAndRatio(LocalDate hireDate, LocalDate requestDate,
                           int expectedYears, int expectedRatioBp) {
        int years = calculator.hireYears(hireDate, requestDate);
        assertThat(years).isEqualTo(expectedYears);
        assertThat(calculator.vestedRatioBp(years)).isEqualTo(expectedRatioBp);
    }

    @Test
    @DisplayName("申请日早于入职日时司龄按 0 处理")
    void requestBeforeHire() {
        assertThat(calculator.hireYears(LocalDate.of(2030, 1, 1), LocalDate.of(2026, 1, 1)))
                .isZero();
        assertThat(calculator.vestedRatioBp(0)).isZero();
    }

    @Test
    @DisplayName("企业缴费归属金额精确到分，不足 1 分舍去")
    void vestedEnterpriseRoundsDownToCent() {
        // 10001 分的 50% = 5000.5 分 -> 5000
        assertThat(calculator.vestedEnterprise(10001L, VestingCalculator.RATIO_50_BP))
                .isEqualTo(5000L);
        // 80%
        assertThat(calculator.vestedEnterprise(10001L, VestingCalculator.RATIO_80_BP))
                .isEqualTo(8000L);
        // 100% 全额
        assertThat(calculator.vestedEnterprise(10001L, VestingCalculator.RATIO_100_BP))
                .isEqualTo(10001L);
        // 0% 不归
        assertThat(calculator.vestedEnterprise(99999L, 0)).isZero();
    }
}

package com.example.starter.pension.service;

import com.example.starter.pension.repo.InstallmentRepository.NewInstallment;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.time.LocalDate;
import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * 分期排期与尾差单元测试：尾差归入最后一期，各期按月初到期，总额等于快照金额。
 */
class InstallmentSchedulerTest {

    private final InstallmentScheduler scheduler = new InstallmentScheduler();

    @Test
    @DisplayName("100 分分 12 期：前 11 期各 8 分，尾差 4 分归入最后一期")
    void remainderGoesToLastInstallment() {
        List<NewInstallment> schedule = scheduler.schedule(
                100L, 12, LocalDate.of(2026, 9, 25));

        assertThat(schedule).hasSize(12);
        for (int i = 0; i < 11; i++) {
            assertThat(schedule.get(i).amountCents()).isEqualTo(8L);
        }
        assertThat(schedule.get(11).amountCents()).isEqualTo(12L);
        assertThat(schedule.stream().mapToLong(NewInstallment::amountCents).sum())
                .isEqualTo(100L);
    }

    @Test
    @DisplayName("10 分分 24 期：前 23 期为 0，尾差 10 分全部归入最后一期")
    void tinyAmountLastInstallmentOnly() {
        List<NewInstallment> schedule = scheduler.schedule(
                10L, 24, LocalDate.of(2026, 1, 15));

        assertThat(schedule).hasSize(24);
        for (int i = 0; i < 23; i++) {
            assertThat(schedule.get(i).amountCents()).isZero();
        }
        assertThat(schedule.get(23).amountCents()).isEqualTo(10L);
        assertThat(schedule.stream().mapToLong(NewInstallment::amountCents).sum())
                .isEqualTo(10L);
    }

    @Test
    @DisplayName("各期按月初 UTC 到期，一次性为申请月月初的 1 期")
    void dueDatesAreMonthStarts() {
        List<NewInstallment> lump = scheduler.schedule(
                500L, 1, LocalDate.of(2026, 9, 30));
        assertThat(lump).hasSize(1);
        assertThat(lump.get(0).dueDate()).isEqualTo(LocalDate.of(2026, 9, 1));
        assertThat(lump.get(0).amountCents()).isEqualTo(500L);

        List<NewInstallment> monthly = scheduler.schedule(
                2400L, 12, LocalDate.of(2026, 1, 31));
        assertThat(monthly.get(0).dueDate()).isEqualTo(LocalDate.of(2026, 1, 1));
        assertThat(monthly.get(11).dueDate()).isEqualTo(LocalDate.of(2026, 12, 1));
        assertThat(monthly.stream().mapToLong(NewInstallment::amountCents).sum())
                .isEqualTo(2400L);
    }
}

